{"action": "replace_code", "code": "def solve(data):
    seen = set()
    duplicates = 0
    events = []
    for event in data['events']:
        if event['eid'] in seen:
            duplicates += 1
            continue
        seen.add(event['eid'])
        events.append(event)

    # Group events by (doc, version)
    groups = {}
    for event in events:
        key = (event['doc'], event['version'])
        if key not in groups:
            groups[key] = []
        groups[key].append(event)

    # For each (doc, version), select winner: delete > put > patch, then lex-max eid
    winners = {}
    losers_set = set()

    for (doc, version), evts in groups.items():
        # Sort by priority: delete=0, put=1, patch=2, then by eid descending
        def priority(e):
            if e['op'] == 'delete':
                return (0, e['eid'])
            elif e['op'] == 'put':
                return (1, e['eid'])
            else:  # patch
                return (2, e['eid'])

        evts_sorted = sorted(evts, key=priority, reverse=True)
        winner = evts_sorted[0]
        winners[(doc, version)] = winner

        # All others are losers for this version
        for e in evts:
            if e != winner:
                losers_set.add(e['eid'])

    # Build documents state
    documents = {}
    for (doc, version), winner in winners.items():
        if doc not in documents:
            documents[doc] = {
                'doc': doc,
                'version': 0,
                'deleted': True,
                'fields': {},
                'history': []
            }
        current = documents[doc]

        # Apply winner's effect
        if winner['op'] == 'delete':
            current['deleted'] = True
            effect = 'deleted'
        elif winner['op'] == 'put':
            current['fields'] = dict(winner['fields'])
            current['deleted'] = False
            effect = 'put'
        else:  # patch
            if current['deleted']:
                effect = 'ignored'
            else:
                # Apply set first, then unset
                current['fields'].update(winner['set'])
                for name in winner['unset']:
                    current['fields'].pop(name, None)
                effect = 'patched'

        current['version'] = version
        current['history'].append({
            'eid': winner['eid'],
            'version': version,
            'effect': effect
        })

    # Ensure all docs mentioned in events (even if no winner) are present
    # Actually, winners dict covers all (doc, version) pairs from events
    # But we need to make sure if a doc only has patch/delete events, it's still in documents
    # The loop above adds doc if not present, so it's covered.

    # Sort documents by doc name
    result_docs = []
    for doc in sorted(documents.keys()):
        current = documents[doc]
        result_docs.append({
            'doc': doc,
            'version': current['version'],
            'deleted': current['deleted'],
            'fields': dict(current['fields']),
            'history': list(current['history'])
        })

    # Convert losers set to sorted list
    losers_list = sorted(losers_set)

    return {
        'documents': result_docs,
        'losers': losers_list,
        'duplicates': duplicates
    }"
}

